const body = $input.all()[0].json.body;

const nom = body.message?.toolCalls?.[0]?.function?.arguments?.nom || "";
const telephone = body.message?.toolCalls?.[0]?.function?.arguments?.telephone || "";
const date_rendez_vous_actuel = body.message?.toolCalls?.[0]?.function?.arguments?.date_rendez_vous_actuel || "";
const nouveau_jour = body.message?.toolCalls?.[0]?.function?.arguments?.nouveau_jour || "";
const nouvelle_heure = body.message?.toolCalls?.[0]?.function?.arguments?.nouvelle_heure || "";
const toolCallId = body.message?.toolCalls?.[0]?.id || "";

// Formater le téléphone avec +1
let telClean = telephone.replace(/\D/g, '');
if (telClean.length === 10) telClean = '1' + telClean;
if (!telClean.startsWith('+')) telClean = '+' + telClean;

// Parser l'heure : "14h00", "14:00", "9h30", "09h00" -> "HH:MM"
function parseHeureFR(texte) {
 let heure = (texte || "").replace('h', ':').replace('H', ':');
 if (!heure.includes(':')) heure = heure + ':00';
 const [h, m] = heure.split(':');
 return h.padStart(2, '0') + ':' + (m || '00').padStart(2, '0');
}

// Parser le jour français en date ISO
const joursFR = ['dimanche','lundi','mardi','mercredi','jeudi','vendredi','samedi'];
const moisFR = ['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'];

function parseJourFR(texte) {
 const lower = (texte || "").toLowerCase().trim();
 const now = new Date();

 // "2026-05-19" déjà en ISO
 if (/^\d{4}-\d{2}-\d{2}$/.test(lower)) return lower;

 // "19 mai", "19 mai 2026", "le 19 mai"
 const matchDateMois = lower.match(/(\d{1,2})\s+(janvier|février|mars|avril|mai|juin|juillet|août|septembre|octobre|novembre|décembre)(?:\s+(\d{4}))?/);
 if (matchDateMois) {
 const jour = parseInt(matchDateMois[1]);
 const mois = moisFR.indexOf(matchDateMois[2]);
 const annee = matchDateMois[3] ? parseInt(matchDateMois[3]) : now.getFullYear();
 const d = new Date(annee, mois, jour);
 return d.toISOString().split('T')[0];
 }

 // "lundi", "mardi prochain", "lundi dans 2 semaines"
 const matchJour = lower.match(/(lundi|mardi|mercredi|jeudi|vendredi|samedi|dimanche)/);
 if (matchJour) {
 const jourCible = joursFR.indexOf(matchJour[1]);
 let diff = jourCible - now.getDay();
 if (diff <= 0) diff += 7;

 // "dans 2 semaines", "dans 3 semaines"
 const matchSemaines = lower.match(/dans\s+(\d+)\s+semaine/);
 if (matchSemaines) {
 diff += (parseInt(matchSemaines[1]) - 1) * 7;
 }
 // "prochain" = semaine prochaine si c'est le même jour
 if (lower.includes('prochain') && diff === 7) diff = 7;

 const d = new Date(now);
 d.setDate(d.getDate() + diff);
 return d.toISOString().split('T')[0];
 }

 // "demain"
 if (lower.includes('demain')) {
 const d = new Date(now);
 d.setDate(d.getDate() + 1);
 return d.toISOString().split('T')[0];
 }

 // "aujourd'hui"
 if (lower.includes("aujourd")) {
 return now.toISOString().split('T')[0];
 }

 // Dernier recours : retourner le texte tel quel
 return lower;
}

const nouveau_jour_iso = parseJourFR(nouveau_jour);
const nouvelle_heure_iso = parseHeureFR(nouvelle_heure);

// Calculer la fin (60 min après)
const startDate = new Date(nouveau_jour_iso + 'T' + nouvelle_heure_iso + ':00');
const endDate = new Date(startDate.getTime() + 60 * 60000);
const pad = (n) => String(n).padStart(2, '0');
const nouvelle_fin_iso = pad(endDate.getHours()) + ':' + pad(endDate.getMinutes());

return [{
 json: {
 nom,
 telephone: telClean,
 date_rendez_vous_actuel,
 nouveau_jour,
 nouvelle_heure,
 nouveau_jour_iso,
 nouvelle_heure_iso,
 nouvelle_fin_iso,
 toolCallId
 }
}];

const events = $input.all();
const dateVoulue = $('Code in JavaScript').first().json.date_rendez_vous_actuel || "";
const toolCallId = $('Code in JavaScript').first().json.toolCallId || "";

if (events.length === 0) {
 return [{ json: { error: "Aucun rendez-vous trouvé", toolCallId } }];
}

if (events.length === 1) {
 return [{ json: { ...events[0].json, toolCallId } }];
}

const joursFR = ['dimanche','lundi','mardi','mercredi','jeudi','vendredi','samedi'];
const moisFR = ['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'];
const lower = dateVoulue.toLowerCase().trim();

for (const event of events) {
 const eventDate = new Date(event.json.start?.dateTime || event.json.start?.date);
 const eventJour = joursFR[eventDate.getDay()];
 const eventJourNum = eventDate.getDate();
 const eventMois = moisFR[eventDate.getMonth()];

 if (lower.includes(eventJour)) return [{ json: { ...event.json, toolCallId } }];
 if (lower.includes(eventJourNum + ' ' + eventMois)) return [{ json: { ...event.json, toolCallId } }];

 const numMatch = lower.match(/\b(\d{1,2})\b/);
 if (numMatch && parseInt(numMatch[1]) === eventJourNum) return [{ json: { ...event.json, toolCallId } }];
}

// Par défaut, retourner le plus proche
events.sort((a, b) => {
 const dateA = new Date(a.json.start?.dateTime || a.json.start?.date);
 const dateB = new Date(b.json.start?.dateTime || b.json.start?.date);
 return dateA - dateB;
});

return [{ json: { ...events[0].json, toolCallId } }];
